import type {
  ArticleSection,
  Branch,
  CitationReference,
  EditorialSource,
  KeyConcept,
  ReadingEntry,
} from '../../types/philosophy';
import {citation as c, paragraph as p, structuredClaim as claim} from './pilotHelpers';

const accessedOn = '2026-08-03';

const source = (
  id: string,
  type: EditorialSource['type'],
  authors: string[],
  title: string,
  url: string,
  note: string,
  year?: number,
  containerTitle?: string,
): EditorialSource => {
  const isStanfordEncyclopediaEntry = url.startsWith('https://plato.stanford.edu/entries/');
  return {
    id,
    type,
    authors,
    title,
    url,
    note,
    ...(year ? {year} : {}),
    ...(containerTitle ? {containerTitle} : {}),
    ...(type === 'scholarly-reference' && isStanfordEncyclopediaEntry ? {
      containerTitle: containerTitle ?? 'The Stanford Encyclopedia of Philosophy',
      publisher: 'Metaphysics Research Lab, Stanford University',
    } : {}),
    accessedOn,
  };
};

const section = (
  prefix: string,
  id: string,
  title: string,
  paragraphs: string[],
  citations: CitationReference[],
  relatedBranchIds?: string[],
  relatedPhilosopherIds?: string[],
  relatedWorkTitles?: string[],
): ArticleSection => ({
  id,
  title,
  paragraphs: paragraphs.map((text, index) => p(`${prefix}-${id}-${index + 1}`, text, citations)),
  ...(relatedBranchIds ? {relatedBranchIds} : {}),
  ...(relatedPhilosopherIds ? {relatedPhilosopherIds} : {}),
  ...(relatedWorkTitles ? {relatedWorkTitles} : {}),
});

const concept = (
  id: string,
  name: string,
  plainDefinition: string,
  deeperExplanation: string,
  example: string,
  relatedConceptIds: string[] = [],
): KeyConcept => ({id, name, plainDefinition, deeperExplanation, example, relatedConceptIds});

const reading = (
  author: string,
  title: string,
  difficulty: ReadingEntry['difficulty'],
  whyRead: string,
  type: ReadingEntry['type'] = 'primary',
  sourceUrl?: string,
): ReadingEntry => ({author, title, difficulty, whyRead, type, ...(sourceUrl ? {sourceUrl} : {})});

