const ontologyArticle: ArticleSection[] = [
  section('ontology', 'orientation', 'Being, existence, and an unsettled field boundary', [
    'Ontology asks what there is, what it is for something to be, and how entities depend on, compose, or differ from one another. Those questions are related but not interchangeable. A census asks whether numbers, properties, organisms, events, possibilities, or institutions exist. A category theory asks what most general kinds they belong to. A dependence inquiry asks which are basic and which obtain in virtue of something else. An inquiry into being may instead ask whether existence has one sense, several modes, or a history concealed by ordinary classification. A responsible field article keeps these projects visible rather than treating ontology as a single list-making technique.',
    'Ontology and metaphysics overlap, but no universally accepted border separates them. “Ontology” was coined in early modern European scholastic settings for a general science of being, while contemporary Anglophone usage often treats it as the inventory-and-category part of metaphysics. Other philosophers use metaphysics more narrowly, treat ontology as fundamental, or reject the distinction. Historical inquiries called first philosophy, analyses of being, Sanskrit category systems, Buddhist critiques of intrinsic nature, and Chinese accounts of generative pattern did not begin as local instances of one modern department. The Atlas may compare them, but comparison must not erase their vocabularies, aims, textual settings, or standards of success.',
    'The field also distinguishes existence from reality, actuality, and fundamentality. A possibility may be real without being actual; an institution may exist without being fundamental; a fictional character may be an object of true discourse without belonging to a theory’s inventory in the same way as its author. Some philosophers defend modes or degrees of being, while others insist that existence is univocal and differences belong elsewhere. Beginner explanations should not settle this dispute by treating “real” as a single everyday adjective. They should ask which contrast is intended, which domain is at issue, and what explanatory work the distinction performs.',
  ], [c('ont-metaphysics-sep', 'section', '1; 2.1–2.3; 4'), c('ont-logic-sep', 'section', '3. Different conceptions of ontology')], ['metaphysics', 'logic']),
  section('ontology', 'existence', 'Existence, quantification, and commitment', [
    'To say that a tiger is striped appears to attribute a feature to a tiger; to say that tigers exist does not obviously add one further feature. Kant, Frege, Russell, and later quantificational approaches helped separate existence claims from ordinary predication, but the resulting consensus is limited. Quine’s influential proposal connects a regimented theory’s ontological commitments with the values of its bound variables: ask what entities must be among the domain for the theory to be true. This provides a disciplined test of commitment, not an automatic proof that first-order notation reveals reality without interpretation.',
    'Commitment depends on which theory and translation one accepts. Mathematics seems to quantify over numbers, science over fields, genes, species, or spacetime points, and law over corporations and offices. Nominalists seek paraphrases or reconstructions that avoid some entities; indispensability arguments defend entities without which successful theory allegedly cannot do its work. Ordinary-language ontologies may recognize tables and debts even when fundamental physics does not use those terms. The question is therefore not merely whether a noun appears, but which explanatory, inferential, and practical roles a theory requires and whether an alternative preserves them without hidden costs.',
  ], [c('ont-logic-sep', 'section', '4.1 Formal languages and ontological commitment'), c('ont-quine', 'section', 'On What There Is')], ['logic', 'philosophy-of-language'], ['quine'], ['On What There Is']),
  section('ontology', 'categories', 'Categories, particulars, properties, and universals', [
    'A category scheme proposes the highest or most general kinds: substances, properties, relations, events, processes, facts, sets, and other candidates. Aristotle’s Categories organizes kinds of predication and being around primary substances, while his Metaphysics asks how substance, form, matter, actuality, and potentiality explain change and priority. Later schemes may aim to describe reality itself, the necessary form of possible objects, the structure of language, or a useful conceptual framework. These aims must be distinguished. A grammatical contrast between noun and verb does not by itself settle whether reality is fundamentally divided into objects and processes.',
    'The problem of universals asks what explains genuine recurrence: two leaves can share green, two actions can exemplify justice, and many objects can stand in the same relation. Realists admit repeatable properties or forms; trope theorists posit particularized property instances; nominalists appeal to resemblance, predicates, classes, or other resources; conceptualists connect universality with thought. “Realism” here does not mean common sense or scientific realism in general. Nor does “particular” mean a featureless atom: events, organisms, persons, and social entities may be particulars under some schemes while having internally structured histories.',
  ], [c('ont-categories-sep', 'section', '1–3; 5'), c('ont-aristotle', 'standard-division', 'Metaphysics Ζ–Θ')], ['metaphysics', 'logic'], ['aristotle'], ['Categories', 'Metaphysics']),
  section('ontology', 'identity-composition', 'Identity, persistence, parts, and wholes', [
    'Identity is governed by the apparently simple principle that each thing is itself, yet persistence makes application difficult. An organism exchanges matter, a river changes water, a statue can survive repair, and a person changes body and psychology. Endurantist accounts say an object is wholly present at different times; perdurantist accounts describe temporal parts; stage theories identify momentary stages linked by counterparts. These labels organize contemporary debate, not an exhaustive cross-cultural map. The practical questions—what was damaged, who is responsible, whether an institution survives reform—often depend on criteria more specific than abstract identity alone.',
    'Mereology studies parts and wholes. Universalists say any things compose a further whole; restrictionists require cohesion, life, function, or another condition; nihilists deny composite objects at a fundamental level. Constitution raises the statue and clay problem: they occupy the same place yet seem to differ in persistence conditions. None of these puzzles proves that ordinary objects are illusions. A layered ontology can distinguish what fundamentally exists from which higher-level objects are real, causally efficacious, or indispensable to explanation. Reduction, dependence, elimination, and harmless redescribing are different conclusions and should not be collapsed.',
  ], [c('ont-metaphysics-sep', 'section', '3.3 Persistence and constitution'), c('ont-categories-sep', 'section', '2 Categories of being')], ['metaphysics']),
  section('ontology', 'events-processes', 'Events, processes, causation, and change', [
    'Ontologies centered on substance face the task of explaining change; process ontologies ask whether enduring things are stabilized patterns within becoming. Events may be property exemplifications, regions of spacetime, changes, or irreducible particulars. Processes unfold and can have phases without being mere sequences of snapshots. A thunderstorm, migration, conversation, metabolism, and legal trial display different internal organization. Treating process as basic can illuminate biology, ecology, and social life, but it does not by itself solve individuation: one must still say where a process begins, which continuities matter, and how processes interact.',
    'Causation and ontology meet when philosophers ask whether causes are events, substances exercising powers, omissions, facts, or variable relations. An absence can explain a plant’s death, although “the missing water” is not straightforwardly an object. Dispositions such as fragility raise related questions: are they real powers, counterfactual patterns, or grounded in categorical structures? The answers affect laws and modality as well as inventory. Ontology should therefore not extract entities from explanatory sentences mechanically. It must distinguish what an explanation refers to, what makes it true, and which structure the explanation represents.',
  ], [c('ont-metaphysics-sep', 'section', '3.4 Causation, freedom and determinism'), c('ont-grounding-sep', 'section', '1. Preliminaries; 4. Interaction with other notions')], ['metaphysics', 'philosophy-of-science'], ['whitehead']),
  section('ontology', 'modality-grounding', 'Possibility, necessity, dependence, and grounding', [
    'Modal ontology asks what makes claims about possibility and necessity true. Possible-worlds talk can be interpreted as commitment to concrete worlds, abstract representations, maximal consistent propositions, or a useful semantic device. Essences, dispositions, laws, and counterfactuals offer other modal resources. It is a mistake to infer from shared notation that modal metaphysicians agree about what possibilities are. Likewise, saying that a fictional character could have acted differently does not automatically add that character to the same inventory as a living person. Different theories explain the truth of such discourse differently.',
    'Grounding is invoked to mark constitutive rather than ordinary causal dependence: a set exists in virtue of its members; a legal status may obtain in virtue of rules and acts; a whole’s feature may be grounded in features of parts. Some treat grounding as a primitive objective relation, some as a form of metaphysical explanation, and some doubt that one relation unifies the cases. Grounding is also more fine-grained than necessity: truths can be necessarily equivalent without either grounding the other. Appeals to “fundamentality” must therefore state whether they concern ontological priority, explanatory order, temporal origin, scale, or practical importance.',
  ], [c('ont-metaphysics-sep', 'section', '3.1 Modality'), c('ont-grounding-sep', 'section', '1–4')], ['metaphysics', 'philosophy-of-language']),
  section('ontology', 'social', 'Social ontology, classification, and power', [
    'Social ontology investigates groups, institutions, money, offices, laws, artifacts, race, gender, disability, and other phenomena constituted or shaped through social interaction. Dependence on practices does not imply illusion. Currency can lose its status when institutions collapse and still have real effects while those institutions endure. A corporation may act through authorized people without being a biological organism. The field distinguishes the constituents of social entities, the conditions that anchor categories, the causal processes that sustain them, and the definitions or functions that make them the kinds they are.',
    'Classification can be both descriptive and world-shaping. Administrative categories allocate rights and risks; medical categories organize care; racialized and gendered categories can be historically constructed while tracking durable patterns of power. Yet not every category is established by explicit agreement, and construction is not a single mechanism. Language, law, material infrastructure, habitual practice, causal feedback, and collective attitudes may interact. Ontological analysis here has political consequences but does not itself settle which institutions deserve endorsement. It must identify who or what produces a category, how it operates, which counterexamples it obscures, and how revision would change the world.',
  ], [c('ont-social-sep', 'section', '2–5')], ['political-philosophy', 'feminist-philosophy'], ['judith-butler']),
  section('ontology', 'comparative', 'Comparison without equivalence', [
    'Sanskrit philosophical traditions developed precise category and dependence debates, but they do not form one “Indian ontology.” Vaiśeṣika classifications include substance, quality, motion, universal, particularity, and inherence, while Nyāya, Mīmāṃsā, Vedānta, Jain, Buddhist, and materialist thinkers disagree about selves, absences, relations, universals, atoms, consciousness, and liberation. Buddhist critiques of svabhāva target independent or intrinsic nature within arguments about dependent arising and soteriological error. Nāgārjuna’s emptiness is not a substance behind appearances and not a claim that nothing conventionally exists. Translating śūnyatā as “nothingness” or anātman as simple Western materialism destroys the argument.',
    'Chinese discussions of dao, you and wu, qi, li, change, generation, and patterned relation likewise cannot be treated as incomplete answers to Aristotle. You and wu are often translated “being” and “nonbeing,” but their uses concern presence, differentiation, availability, and generation in specific texts. The Daodejing and Zhuangzi resist fixed naming for ethical, political, and cosmological reasons, while later Confucian and Buddhist thinkers develop different ontological projects. Similarities to process philosophy or relational ontology can open questions; they do not establish direct influence or one-to-one identity. Globally responsible ontology makes translation choices and non-equivalence visible.',
    'Islamic philosophical traditions also resist the role of a simple bridge. Al-Fārābī, Avicenna, Suhrawardī, Ibn ʿArabī, Mullā Ṣadrā, and their critics develop distinct accounts of essence, existence, necessity, illumination, gradation, and substantial motion in conversation with theology and inherited Greek texts. Latin scholastic receptions sometimes transform these arguments while later histories obscure the transformation. Saying that Avicenna “anticipated” a European distinction can identify a useful chronology, but it can also make the later vocabulary the measure of the earlier project. Comparison should track texts, translations, institutions, and argumentative uptake before asserting influence.',
  ], [c('ont-chinese-sep', 'section', '1–3; 6'), c('ont-buddhist-sep', 'section', '2–3'), c('ont-dao', 'standard-division', 'Chapters 1, 2, 11, 25, and 40')], ['chinese-philosophy', 'indian-philosophy', 'buddhist-philosophy', 'daoism'], ['kanada', 'nagarjuna', 'laozi', 'zhuangzi']),
  section('ontology', 'metaontology', 'Metaontology: what is an ontological dispute?', [
    'Metaontology asks what ontologists are doing and how apparent disagreements should be adjudicated. Carnap distinguishes questions asked within a linguistic framework from practical external questions about adopting a framework. Quine rejects a sharp analytic boundary and seeks commitment through regimented best theory. Later deflationists argue that some disputes are shallow, verbal, or easily settled by ordinary conceptual rules; realists defend substantive answers constrained by reality. The positions are not captured by saying Carnap disliked existence questions and Quine liked them: both care about language, theory, and disciplined inquiry but disagree about framework choice and the reach of factual dispute.',
    'Methodological evidence in ontology includes logic, linguistic practice, science, explanatory power, intuitions about cases, conceptual genealogy, and attention to lived or social phenomena. Each can mislead. Formal consistency does not guarantee worldly application; current science may not decide every category; ordinary language carries historical assumptions; intuitions vary with framing and training. A defensible ontology states its target domain, its level of inquiry, its criteria of adequacy, and the costs of rivals. Sometimes plural schemes answer different questions; sometimes they conflict about the same world. “Pluralism” should not become an excuse to avoid identifying which situation obtains.',
    'Ontological engineering adds a practical question: should inherited categories be revised to serve better epistemic or political purposes? A category can misrepresent a phenomenon, coordinate useful action, or impose an unjust social position. Ameliorative projects distinguish what a term currently means, which phenomenon explains its use, and what concept should guide future practice. That work remains answerable to the world and to affected people; it is not free invention. It also shows why ontology and politics can interact without collapsing into one another. Facts about construction constrain reform, while judgments about justice cannot be derived from metaphysical dependence alone.',
  ], [c('ont-carnap', 'section', 'Internal and external questions'), c('ont-quine', 'section', 'On What There Is'), c('ont-logic-sep', 'section', '3.1–3.2; 4.4–4.6')], ['logic', 'philosophy-of-language', 'philosophy-of-science'], ['carnap', 'quine']),
  section('ontology', 'reading', 'A reading path through rival ontological projects', [
    'Begin with Aristotle’s Categories and selected books of the Metaphysics, asking separately about predication, substance, change, and being. Then compare a carefully introduced Vaiśeṣika category text, a Buddhist argument about dependent arising, and passages from the Daodejing or Zhuangzi. The purpose is not to select a winner or manufacture a shared doctrine. Record what problem each text recognizes, the practical or liberatory stakes of its categories, and which translations are interpretive. Add Avicenna on essence and existence to see how Arabic philosophical theology transformed Greek inheritances rather than merely preserving them.',
    'For contemporary work, read Carnap beside Quine, then study one dispute each about universals, composition, modality, grounding, and social ontology. Build a small domain ontology—for a hospital, archive, watershed, or online community—and mark where choices are physical, biological, legal, technical, or normative. Ask whether a change of schema redescribes an unchanged world or alters institutional possibilities. End by returning to the field boundary: ontology can inventory, categorize, explain dependence, diagnose a conceptual scheme, or interrogate being. Its unity is a continuing argument, not a definition established once and for all.',
  ], [c('ont-aristotle', 'standard-division', 'Categories; Metaphysics Γ, Ζ, Θ'), c('ont-carnap', 'section', 'Internal and external questions'), c('ont-quine', 'section', 'On What There Is'), c('ont-social-sep', 'section', '2–5')], ['metaphysics', 'logic', 'philosophy-of-language'], ['aristotle', 'avicenna', 'carnap', 'quine']),
];

const politicalArticle: ArticleSection[] = [
  section('political-philosophy', 'orientation', 'The justification, organization, and contestation of power', [
    'Political philosophy asks how shared power should be organized, justified, limited, resisted, and transformed. It investigates authority and obligation, liberty and equality, justice and law, rights and property, citizenship and borders, democracy and expertise, violence and resistance. It also asks how family, labor, class, race, gender, disability, religion, empire, technology, and ecological dependence structure political standing. These are analytical and normative questions, but they cannot be answered responsibly without history and social inquiry. A concept of freedom that ignores who can actually move, speak, work, care, or survive may protect a formally equal status while leaving domination intact.',
    'The field is not current party commentary, a list of ideal constitutions, or a European sequence from Plato to social contract to liberal democracy. Textual traditions around the world have argued about rule, cultivated character, law, office, punishment, common goods, hierarchy, rebellion, land, kinship, and relations among peoples. Activist theory, legal argument, institutional design, religious reasoning, oral traditions, and anticolonial struggle can all contain philosophical work. Their genres and standards differ. Bringing them into one article should reveal distinct questions and encounters, not retroactively award every author membership in a modern academic field.',
  ], [c('pol-authority-sep', 'section', '1–2'), c('pol-justice-sep', 'section', '1–3'), c('pol-africana-sep', 'section', '1. What Africana Philosophy Is')], ['ethics', 'feminist-philosophy']),
  section('political-philosophy', 'authority', 'Authority, legitimacy, obligation, and law', [
    'De facto authority concerns effective rule or accepted command; normative authority concerns a justified status. Even normatively, theorists distinguish a liberty to issue and enforce directives, a power to alter subjects’ duties, and a claim-right to rule. Legitimacy may refer to justified coercion, justified institutions, or decisions produced by acceptable procedures. These distinctions matter because a state might be justified in preventing violence without possessing a general power to make every command morally binding. Conversely, a citizen can have an independent duty not to harm others even when the institution announcing that rule lacks legitimacy.',
    'Political obligation asks whether people have a general duty to obey law because it is law. Consent, fair play, gratitude, association, natural duty, democratic equality, and beneficial coordination offer rival grounds; philosophical anarchists deny that any establishes the sweeping authority states claim. Legality and legitimacy therefore diverge. Rule of law can limit arbitrariness while administering grave injustice, and conscientious refusal can violate valid law without being mere lawlessness. A complete analysis distinguishes the state’s justification, an officeholder’s authority, a particular law’s justice, a subject’s reasons, and the permissibility of enforcement.',
    'Law is also more than the commands of a sovereign. Constitutional rules distribute offices and jurisdiction; administrative systems translate policy into classifications and procedures; customary, religious, Indigenous, international, and transnational legal orders can overlap or conflict. Legal positivists separate what law is from what it ought to be, while natural-law and interpretivist theories connect legal validity, reason, and moral principle in different ways. Legal pluralism can describe real normative orders without implying that every rule is equally just. Political philosophy asks which institutions may decide conflicts and whose law colonial states have displaced or refused to recognize.',
  ], [c('pol-authority-sep', 'section', '1.1–1.2; 2'), c('pol-legitimacy-sep', 'section', '1–4'), c('pol-hobbes', 'chapter', 'Part II, chapters 17–21 and 26')], ['ethics']),
  section('political-philosophy', 'liberty-equality', 'Liberty, equality, rights, and domination', [
    'Negative liberty is commonly framed as freedom from interference; positive liberty concerns self-direction or effective control; republican liberty emphasizes security from arbitrary power. Capability approaches ask what people are genuinely able to do and be. These are families of views, not three dictionary meanings that map neatly onto ideologies. Noninterference can coexist with dependence on a master who chooses not to intervene, while formal permission can be useless without resources, accessibility, or social recognition. Collective self-government may enhance freedom yet also impose decisions on dissenters. Political liberty requires an account of agents, obstacles, institutions, and valued activities.',
    'Equality can concern moral standing, law, political voice, opportunity, resources, welfare, capability, recognition, or social relations free of rank. Rights can protect interests, choices, status, or institutional guarantees; human rights raise questions about universality, enforcement, and cultural or political justification. Liberty and equality are not natural opposites: concentrated property may protect one owner’s options while undermining others’ independence and public equality. Nor does equality require identical treatment when environments exclude. Disability justice shows why accommodation, accessible design, recognition, and altered social practices can be requirements of equality rather than exceptions to it.',
  ], [c('pol-justice-sep', 'section', '2–6'), c('pol-disability-sep', 'section', '1–7'), c('pol-mill', 'chapter', 'Chapters I–III')], ['ethics', 'feminist-philosophy']),
  section('political-philosophy', 'justice-property-class', 'Justice, property, labor, and class', [
    'Justice covers more than distributing income. Corrective justice addresses wrongs between parties; procedural justice evaluates how decisions are made; substantive justice evaluates results or rules; recognition concerns standing and interpretation; rectificatory justice confronts histories of theft, enslavement, dispossession, exclusion, and violence. Distributive theories compare welfare, resources, primary goods, capabilities, need, desert, sufficiency, equality, and entitlement. A snapshot can hide the history that produced holdings, while a purely historical theory still needs principles for acquisition, transfer, collective goods, ecological limits, and rectification.',
    'Property is a bundle of powers, liberties, claims, and immunities arranged by law and practice, not simply a prepolitical object-state relation. Political economy asks how ownership, markets, workplaces, care, debt, and public provision organize power. Marxist theories make class and exploitation central; socialist, social-democratic, anarchist, republican, liberal, Indigenous, feminist, and other traditions offer different diagnoses. Class never operates in a vacuum: racialized dispossession, gendered reproductive labor, caste, disability, migration status, and colonial extraction shape work and wealth. Explaining those relations is neither reducing every injustice to class nor treating class as optional.',
  ], [c('pol-justice-sep', 'section', '2–6'), c('pol-colonialism-sep', 'section', '1–4'), c('pol-combahee', 'work', 'The Combahee River Collective Statement')], ['marxism', 'feminist-philosophy', 'ethics'], ['marx', 'angela-davis']),
  section('political-philosophy', 'democracy', 'Democracy, representation, expertise, and citizenship', [
    'Democracy can be defended instrumentally for producing responsive or informed decisions and intrinsically as equal standing, collective self-rule, or public justification. Voting is only one institution within democratic systems. Agenda setting, parties, legislatures, courts, workplaces, media, protest, associations, local governance, sortition, and deliberative forums distribute voice and control. Majority rule faces persistent-minority and boundary problems: who belongs to the demos, which decisions may majorities make, and how do colonial subjects, residents, children, nonhuman interests, and future generations receive standing? No procedural formula makes these questions disappear.',
    'Citizenship combines legal status, rights, duties, identity, and practices of participation, but it can also mark exclusion. Normative theory disputes whether representatives should mirror constituents, follow mandates, exercise judgment, or construct constituencies through political work. Expertise creates another tension: complex decisions need knowledge, yet experts are fallible, socially positioned, and not authorized to choose all public values. Democratic institutions require ways to scrutinize expertise without pretending specialized knowledge is just preference. The field does not converge on liberal democracy; epistocracy, republicanism, socialism, anarchism, agonism, deliberation, participatory models, and critiques of the state remain live alternatives.',
  ], [c('pol-democracy-sep', 'section', '1–7'), c('pol-authority-sep', 'section', '2.6 Democratic conceptions')], ['epistemology', 'political-philosophy']),
  section('political-philosophy', 'power-violence', 'Power, violence, resistance, and nonideal theory', [
    'Power is not exhausted by commands backed by force. Institutions shape agendas, options, subject positions, knowledge, and what appears normal; economic dependence and social norms can secure compliance without an explicit threat. Some theories emphasize power exercised over others, some collective power to act, and some productive networks through which agents are formed. Violence is likewise contested: physical force, structural deprivation, state coercion, colonial occupation, and symbolic injury should not be merged without criteria. Philosophical analysis can distinguish them while still showing their interaction. Explanation of why violence occurs is not endorsement of its use.',
    'Resistance ranges from litigation, strikes, refusal, flight, mutual aid, civil disobedience, and sabotage to revolution and armed struggle. Justification depends on aims, agents, targets, proportionality, alternatives, likely consequences, and the background distribution of violence. Nonideal theory begins from actual injustice, partial compliance, and distorted institutions; it asks what diagnosis and action are possible now. Ideal principles can identify direction or standards, but idealization can erase the very histories and agents that make injustice intelligible. Activist theory supplies concepts and knowledge from struggle, yet movements are internally contested and cannot be treated as infallible collective authors.',
    'State violence presents special problems because public offices claim authorization and regularize force through police, military, border, prison, and emergency institutions. Formal accountability can coexist with impunity, while informal community control can reproduce hierarchy. Pacifist, just-war, self-defense, revolutionary, abolitionist, and nonviolent traditions disagree about whether legitimate violence exists and how means shape ends. “Order” cannot be treated as a neutral baseline when the background is dispossession or domination. Yet condemning structural violence does not remove duties to distinguish direct targets, foreseeable harms, and agents’ responsibility for particular acts.',
  ], [c('pol-feminist-sep', 'section', '2. Contemporary approaches and debates'), c('pol-race-sep', 'section', '1–5'), c('pol-combahee', 'work', 'The Combahee River Collective Statement')], ['continental-philosophy', 'feminist-philosophy', 'marxism'], ['arendt', 'foucault', 'fanon', 'angela-davis']),
  section('political-philosophy', 'empire-race-gender', 'Empire, race, gender, and the limits of canonical universals', [
    'European theories of natural law, contract, property, civilization, and progress developed amid conquest, slavery, settlement, and empire. Their universal terms could criticize domination and also rationalize tutelage or exclusion. Colonialism is political domination, not merely cultural contact, and settler colonialism, indirect rule, enslavement, extraction, and imperial administration have distinct forms. Anticolonial thinkers analyze how sovereignty, economy, racial hierarchy, culture, and subjectivity interact. A canon should not be “balanced” by adding Fanon after an unchanged contract story; colonial relations alter how the central concepts themselves must be read.',
    'Feminist political philosophy shows how a public/private boundary can hide household domination, reproductive labor, sexual violence, dependency, and care. Black feminist and intersectional work analyzes institutions that cannot be understood on one axis at a time. Critical philosophy of race examines racism as historical and structural, not only individual prejudice. These interventions do not form one doctrine: liberal rights, Marxist social reproduction, radical feminism, abolition, decolonial feminism, Indigenous resurgence, queer and trans politics, and care-centered theories disagree about state power, identity, law, coalition, and freedom. The disagreements belong inside political philosophy, not in a final “applications” appendix.',
  ], [c('pol-colonialism-sep', 'section', '1–5'), c('pol-feminist-sep', 'section', '1–2'), c('pol-race-sep', 'section', '1–5'), c('pol-combahee', 'work', 'The Combahee River Collective Statement')], ['feminist-philosophy', 'marxism'], ['fanon', 'angela-davis', 'bell-hooks']),
  section('political-philosophy', 'global', 'Borders, global justice, ecology, and future generations', [
    'States govern territory and membership, but trade, finance, war, emissions, migration, health, and information cross borders. Global justice asks whether duties arise from common humanity, harmful interaction, shared institutions, historical responsibility, or special relationships. Cosmopolitans and statists disagree about the moral importance of borders and coercive structures; theories of self-determination disagree about peoples, secession, and Indigenous sovereignty. Humanitarian intervention must confront both atrocity and imperial abuse. Migration theory examines exclusion, refuge, labor, family, and political membership rather than treating a border as an unquestioned owner’s fence.',
    'Climate injustice joins historical emissions, unequal vulnerability, development, extraction, adaptation, loss, and duties to future generations. Those not yet born cannot vote, while communities least responsible may face the greatest harm. Environmental policy also affects Indigenous land relations and nonhuman beings whose standing is disputed. Allocation by ability, benefit, contribution, need, or equal shares yields different results. Public-health crises similarly connect expertise, trust, coercion, global production, and unequal exposure. Political philosophy contributes normative distinctions, but institutional design requires empirical knowledge and participation by people whose lives are governed.',
  ], [c('pol-global-sep', 'section', '1–11'), c('pol-colonialism-sep', 'section', '1–5')], ['ethics', 'philosophy-of-science']),
  section('political-philosophy', 'plural-genealogies', 'Plural genealogies and responsible comparison', [
    'Classical Greek arguments about constitutions and citizenship are one genealogy. Confucian debates over humane rule, ritual, cultivated officials, remonstrance, and the people’s welfare; Mohist standards of benefit and opposition to aggressive war; and traditions retrospectively grouped as Legalist analyze institutions and statecraft through different vocabularies. Islamic philosophers and jurists debate virtuous rule, law, revelation, caliphate, community, and governance; Africana traditions encompass ancient, Islamic, Indigenous, diasporic, liberation, feminist, and postcolonial projects. None is a single cultural answer. “Harmony,” “community,” or “consensus” can conceal conflict, hierarchy, and institutional detail when used as civilizational labels.',
    'Comparison should specify its unit: a concept, argument, institution, genre, historical encounter, or later reception. It should ask whether traditions transmitted texts or instead developed analogous questions independently. Concepts such as rights, sovereignty, personhood, ubuntu, dao, li, sharia, caste, kinship, and land do not occupy identical semantic fields. Comparative political philosophy can expose assumptions—especially the image of an independent contracting individual or a territorially sovereign state—but only if it resists turning non-European materials into illustrations of categories fixed elsewhere. Global responsibility requires multiple centers of argument and explicit translation choices.',
    'Indigenous political philosophies often understand land, jurisdiction, kinship, responsibility, and treaty through living legal and intellectual traditions rather than through a single doctrine of communal ownership. Settler states may recognize fragments while denying underlying sovereignty. Africana political thought ranges across ancient state traditions, Indigenous concepts, Islamic intellectual worlds, enslavement and diaspora, anticolonial liberation, Pan-Africanism, Black feminism, and contemporary democratic argument. Labels such as “communitarian” can illuminate one contrast but also flatten disputes over individuality, authority, gender, class, and coercion. No civilization speaks with one political voice.',
  ], [c('pol-africana-sep', 'section', '1–4'), c('pol-feminist-sep', 'section', '2.7 Transnational, postcolonial, and decolonial feminisms'), c('pol-colonialism-sep', 'section', '1–5')], ['chinese-philosophy', 'islamic-philosophy', 'feminist-philosophy'], ['confucius', 'mozi', 'han-feizi', 'al-farabi', 'fanon']),
  section('political-philosophy', 'reading', 'Reading institutions as well as ideals', [
    'Begin with sharply different primary problems: Plato on justice and education, Confucius or Mencius on cultivated rule and remonstrance, Mozi on public benefit, al-Farabi on the virtuous city, and Hobbes on authorization under insecurity. Read states of nature as argumentative devices rather than universal prehistory. Then pair Locke, Rousseau, Mill, Wollstonecraft, and Marx with the property, empire, gender, labor, and exclusion each text addresses or reproduces. A reading path should ask who speaks, who counts as a subject, what institution is being justified, and what historical power the abstraction leaves outside view.',
    'For contemporary study, compare democratic, republican, libertarian, socialist, feminist, anticolonial, capabilities, disability-justice, abolitionist, Indigenous, and global-justice arguments around one concrete institution. Separate diagnosis from endorsement and principles from implementation. Read the Combahee River Collective Statement as political theory rooted in organizing, not as a demographic supplement. Test any proposed ideal against access, enforcement, transition, unintended effects, and the agency of affected people. Political philosophy is mature when it can move among concepts, histories, social evidence, movement knowledge, and institutional design without pretending that these forms of reasoning are interchangeable.',
  ], [c('pol-hobbes', 'chapter', 'Parts I–II'), c('pol-mill', 'chapter', 'Chapters I–V'), c('pol-combahee', 'work', 'The Combahee River Collective Statement'), c('pol-democracy-sep', 'section', '1–7')], ['ethics', 'feminist-philosophy', 'marxism'], ['plato', 'confucius', 'mozi', 'al-farabi', 'hobbes', 'mill', 'wollstonecraft', 'marx']),
];

const mindArticle: ArticleSection[] = [
  section('philosophy-of-mind', 'orientation', 'Mind is not one problem', [
    'Philosophy of mind studies consciousness, thought, perception, embodiment, action, emotion, memory, selfhood, agency, and the ways minds relate to bodies, worlds, and other minds. Some questions are metaphysical: what kinds of things mental states are. Some are epistemological: how we know our own and others’ minds. Some are phenomenological: how experience is structured from a first-person perspective. Cognitive science asks how capacities operate; ethics asks which beings can suffer or deserve respect; political theory asks whose speech, rationality, memory, or agency institutions recognize. A comprehensive field article keeps these dimensions connected without pretending that one answer settles all of them.',
    'The familiar “mind-body problem” is therefore a family of problems. Explaining how neural activity realizes a cognitive capacity does not automatically explain subjective experience; establishing that culture shapes emotion does not show that biology is irrelevant; showing that tools support memory does not by itself make every external resource part of a person. Theories compete over targets as well as answers. Philosophy clarifies concepts and arguments while learning from neuroscience, psychology, psychiatry, linguistics, computer science, anthropology, disability studies, and animal research. Scientific findings constrain philosophy, but data acquire evidential force through models and interpretations that also require scrutiny.',
    'Method matters because first-person reports, behavioral measures, neural recordings, computational models, ethnography, conceptual analysis, and historical texts answer different questions. Introspection can reveal how experience seems while missing its causes; laboratory control can isolate a variable while stripping away everyday skill; neuroimaging can localize covariance while overstating reverse inference. Philosophical thought experiments test concepts but may depend on culture-bound intuitions or impossible stipulations. Strong inquiry uses several methods, states which conclusion each supports, and does not promote one evidential access route into a complete definition of mind.',
  ], [c('mind-consciousness-sep', 'section', '1–2; 4–7'), c('mind-intentionality-sep', 'section', '1–10'), c('mind-embodied-sep', 'section', '1–4')], ['metaphysics', 'epistemology', 'phenomenology']),
  section('philosophy-of-mind', 'histories', 'Many histories of mind and person', [
    'Greek accounts of soul, perception, intellect, and embodied life; late antique and medieval Arabic, Jewish, Christian, and Latin theories of faculties; and early modern debates over thinking substance, matter, mechanism, and animal life are important genealogies, not the field’s sole origin. Descartes made the real distinction between thinking and extended substance canonical in later European debate, yet the Meditations also distinguishes intellect from imagination and treats the embodied human being as more than a pilot in a ship. Elisabeth of Bohemia’s interaction challenge and alternatives from Hobbes, Spinoza, Conway, Leibniz, Locke, Hume, and others show that “Cartesian dualism versus materialism” never exhausted the early modern terrain.',
    'Classical Indian philosophers debate ātman, person, body, senses, consciousness, reflexive awareness, memory, and liberation across Nyāya, Vaiśeṣika, Mīmāṃsā, Vedānta, Jain, Buddhist, and materialist schools. Indian Buddhist accounts analyze streams of conditioned mental and physical events without an independent enduring self, but schools disagree about persons, reflexivity, representation, and continuity. Classical Chinese xin is often translated “heart-mind” because cognition, emotion, attention, judgment, and cultivation are not organized by a Cartesian mental/physical divide. These materials are not primitive functionalism, phenomenology, or neuroscience. Comparison is responsible only when it preserves their technical vocabulary and ethical or soteriological aims.',
  ], [c('mind-dualism-sep', 'section', '2. History of dualism'), c('mind-buddhist-sep', 'section', '1–6'), c('mind-chinese-sep', 'section', '1–5'), c('mind-indian-person-sep', 'section', '1–5'), c('mind-descartes', 'standard-division', 'Meditations II and VI')], ['indian-philosophy', 'buddhist-philosophy', 'chinese-philosophy', 'rationalism'], ['descartes', 'anne-conway', 'vasubandhu', 'dignaga', 'dharmakirti', 'confucius']),
  section('philosophy-of-mind', 'consciousness', 'Consciousness and subjective character', [
    '“Consciousness” can mean wakefulness, access to information for reasoning and report, awareness of an object, self-consciousness, or phenomenal experience—what it is like for a subject. A theory may explain discrimination and flexible control while leaving disputed whether it explains feeling; another may illuminate phenomenal unity without explaining access or function. The so-called hard problem asks why and how physical or functional processes are accompanied by experience, but even its formulation is contested. Some argue that solving the right cognitive and representational problems dissolves the residue; others defend irreducible phenomenal facts, identity views, panpsychism, neutral monism, or forms of dualism.',
    'Nagel’s bat argument emphasizes the subjective character of experience and a gap between objective description and knowing what another creature’s life is like. It does not by itself prove that experience is nonphysical or scientifically inaccessible. Knowledge arguments, conceivability arguments, explanatory-gap claims, illusionism, higher-order theories, global-workspace approaches, integrated-information proposals, predictive-processing frameworks, and recurrent-processing accounts target different explanatory demands. Evidence from report, behavior, metacognition, neural perturbation, and comparative study remains methodologically difficult. Consciousness is an open research area because no proposal commands agreement across conceptual adequacy, empirical support, and metaphysical interpretation—not because nothing can be learned.',
    'Unity and temporality create additional problems. Experience appears as a coordinated field despite processing distributed across modalities and time; the present has duration rather than being a mathematical instant. Split-brain cases, masking, rivalry, anesthesia, dreaming, and disorders of consciousness test whether access, report, integration, and subject unity come apart. “Level” and “contents” of consciousness are useful clinical distinctions but can hide graded or multidimensional organization. Ethical decisions about patients require operational evidence and humility: a diagnostic category should not be confused with certainty about the absence of experience.',
  ], [c('mind-consciousness-sep', 'section', '1–6'), c('mind-nagel', 'section', 'What Is It Like to Be a Bat?'), c('mind-physicalism-sep', 'section', '4–7')], ['metaphysics', 'philosophy-of-science'], ['thomas-nagel']),
  section('philosophy-of-mind', 'intentionality', 'Intentionality, content, and representation', [
    'Intentionality is the directedness or aboutness of many mental states: a belief can concern tomorrow’s weather, a fear can be of a nonexistent threat, and a desire can represent a possible outcome. It is not the same as intending to act. Nor is it identical with consciousness; unconscious beliefs may have content, and pains may be conscious even when their intentional structure is disputed. Philosophers ask how thoughts refer, what determines their correctness conditions, whether content is narrow or environment-dependent, and how misrepresentation is possible. Brentano’s claim that intentionality marks the mental shaped later debate, but not every theory accepts it as a necessary and sufficient criterion.',
    'Representationalism explains some or all phenomenal character through representational content; phenomenal-intentionality theories reverse or complicate the priority by grounding some content in experience. Computational and teleosemantic approaches seek naturalistic accounts through causal, functional, informational, or biological relations. Externalists argue that content partly depends on the environment or linguistic community. Enactivists challenge pictures of content as inner symbols detached from skilled engagement. Each strategy must explain error, absent objects, conceptual thought, and first-person significance. “The brain processes information” is not yet an account of semantic content unless information, consumer systems, norms, and representational success are specified.',
    'Collective and linguistic intentionality complicate the picture further. A promise, plan, scientific model, or currency can have content through public practices that no isolated brain established. Some philosophers derive public representation from individual intentions; others argue that socially instituted norms help constitute individual thought. Content externalism can make a thinker’s environment partly determine what they believe, yet first-person authority may persist because avowal does not require surveying those determinants. The issue connects mind to language and social ontology without showing that private experience is merely linguistic.',
  ], [c('mind-intentionality-sep', 'section', '1–10'), c('mind-embodied-sep', 'section', '3. Enactivism'), c('mind-consciousness-sep', 'section', '6. Theories of consciousness')], ['philosophy-of-language', 'epistemology']),
  section('philosophy-of-mind', 'perception', 'Perception, sensation, and the world', [
    'Perception seems to put subjects in contact with a world, yet illusion and hallucination show that experience can mislead. Sense-data theories, adverbial views, representationalism, and naïve or direct realism explain the commonalities and differences differently. Philosophers debate whether perceptual content is conceptual, whether experience itself provides reasons, and how attention alters what is available. Multisensory integration, proprioception, pain, spatial orientation, and interoception complicate a vision-centered model. Perception is active and temporally extended: eyes, hands, posture, expectation, and movement help determine how a scene is encountered.',
    'Phenomenology studies the meaningful organization of appearance, including figure and ground, horizon, bodily orientation, temporality, and the fact that objects appear as usable or threatening before detached judgment. Ecological and sensorimotor theories emphasize organism-environment relations and learned patterns of exploration. Neuroscience identifies processing pathways and causal dependencies, but neural decoding does not on its own decide whether experience is representational or relational. Social position also shapes habitual attention and affordances without making perception arbitrary. A doorway, police presence, face, or staircase can solicit different possibilities for agents with different bodies and histories while remaining publicly investigable.',
    'Pain resists a simple model of perception. It has sensory qualities, motivates protection, can persist without current tissue damage, and is influenced by attention, expectation, social meaning, and prior injury. Treating pain as infallible inner detection misses these dimensions; treating it as mere behavior licenses harmful disbelief. Similar issues arise with phantom sensation, chronic fatigue, interoception, and psychiatric experience. A layered account can recognize first-person authority about suffering, causal complexity, diagnostic uncertainty, and the possibility that institutions systematically underrate some speakers. Philosophy clarifies why those commitments need not conflict.',
  ], [c('mind-embodied-sep', 'section', '2–3'), c('mind-consciousness-sep', 'section', '2; 5–6'), c('mind-chinese-sep', 'section', '3–5')], ['phenomenology', 'epistemology'], ['husserl', 'merleau-ponty']),
  section('philosophy-of-mind', 'embodiment', 'Embodiment, enactivism, and extended cognition', [
    'Embodied cognition is a research family, not the slogan that brains do not matter. Some weak theses say bodily structure constrains processing; stronger theses say bodily action partly constitutes cognition. Embedded approaches emphasize environmental scaffolding; enactivist approaches explain sense-making through autonomous living activity or sensorimotor skill; extended-mind views argue that under some conditions external resources are constituents of cognitive processes. These positions disagree about representation, computation, biological autonomy, and the boundary of the cognitive. Grouping them as “4E cognition” is convenient, but the acronym should not conceal different arguments.',
    'Clark and Chalmers’s notebook case asks whether a reliably available external resource can play a role sufficiently like biological memory to count as part of a cognitive system. Critics question parity, ownership, coupling, portability, and the distinction between a cause of cognition and a constituent. Disability practices make the issue concrete: canes, communication devices, calendars, interpreters, medication, and accessible environments can transform agency without all doing so in the same way. Philosophical analysis should neither romanticize dependence nor protect an isolated-brain boundary by definition. It should identify the integrated system, timescale, function, vulnerability, and social infrastructure that make a capacity possible.',
    'Embodiment also includes affect, metabolism, fatigue, hormonal regulation, development, and mortality, not just limbs executing a neural plan. Skill can be sedimented in posture and timing so that an agent responds without calculating a representation of every movement. Social norms organize bodies by training gesture, proximity, clothing, and permissible action. Critical phenomenology studies how race, gender, disability, and colonial history shape bodily orientation while avoiding the claim that every member of a group experiences one world. Bodies are biological and socially interpreted; neither description cancels the other.',
  ], [c('mind-embodied-sep', 'section', '1–5'), c('mind-extended', 'section', 'The Extended Mind')], ['phenomenology', 'philosophy-of-science']),
  section('philosophy-of-mind', 'action', 'Action, intention, agency, and practical knowledge', [
    'An event can match what an agent wanted without being an action: a nervous movement might accidentally produce the desired result. Causal theories explain intentional action through appropriately related beliefs, desires, intentions, or plans; noncausal and agent-causal theories deny that ordinary event causation captures agency. Anscombe’s question “Why?” connects intentional descriptions with an agent’s practical knowledge: one movement can be pumping water, poisoning inhabitants, or moving an arm under different descriptions. Philosophy of mind asks how intentions guide unfolding action, how agents know what they are doing, and how deviant causal chains are excluded.',
    'Agency comes in degrees and kinds. Habitual, skilled, collective, infant, animal, and impaired action may not fit a model of explicit deliberation followed by command. Sense of agency can diverge from actual control, as clinical and experimental cases show. Structural conditions shape available options without turning persons into passive objects; conversely, attributing agency should not excuse coercion or blame people for constrained choices. Free-will debates concern alternative possibilities, sourcehood, reasons-responsiveness, and responsibility, but agency is wider than moral responsibility. The ability to initiate, sustain, revise, and own activity can matter even where praise and blame are inappropriate.',
    'Collective agency asks when a group can intend, decide, and act rather than merely aggregate members’ behavior. Committees, movements, firms, and states have procedures, roles, memory, and commitments that can outlast participants, yet every group act is materially carried by people and artifacts. Individualist accounts reduce group states to members and organization; nonreductive accounts defend group-level attitudes or agents. The ethical stakes are substantial: attributing corporate responsibility should not erase individual decisions, while refusing all group agency can make organized harms and obligations difficult to name.',
  ], [c('mind-causation-sep', 'section', '1.1; 7.4–7.5'), c('mind-embodied-sep', 'section', '2–4')], ['ethics', 'political-philosophy'], ['anscombe']),
  section('philosophy-of-mind', 'emotion', 'Emotion, feeling, appraisal, and social meaning', [
    'Emotions combine bodily change, feeling, appraisal, attention, motivation, expression, and social interpretation in ways that resist one essence. James famously asks whether bodily responses help constitute emotion rather than merely follow an inner feeling. Judgment and appraisal theories stress evaluations; perceptual theories treat emotions as ways values appear; constructionist and cultural approaches examine learned concepts and practices. Fear can disclose danger and still be mistaken; grief can be fitting without being instrumentally useful. Calling emotions irrational ignores their reasons and intelligence, while calling them judgments alone can neglect bodily and affective texture.',
    'Emotional repertoires are socially trained and politically interpreted. Anger from marginalized speakers may be pathologized, while fear from dominant groups can authorize coercion. Shame, pride, disgust, love, grief, and resentment have interpersonal histories and normative dimensions. This does not reduce emotion to discourse: physiology, development, temperament, trauma, and environment matter. Chinese heart-mind traditions and Buddhist analyses of affective dispositions offer resources for understanding cultivation, attention, and suffering, but they should not be translated into contemporary emotion-regulation therapies without textual and institutional context. Philosophy asks both what emotions are and when attending to them improves judgment.',
    'Mood and emotion also differ. An emotion is often directed toward a particular object, while anxiety, depression, elation, or boredom can disclose the world as a whole field of possibility. Clinical categories identify patterns that may demand support, but their boundaries reflect measurement, impairment judgments, and cultural expectations as well as physiology. Emotion regulation can mean suppression, reinterpretation, environmental change, relationship repair, or political action. The demand that an individual privately regulate a fitting response may preserve the condition that makes it recur.',
  ], [c('mind-james', 'chapter', 'Chapter XXV: The Emotions'), c('mind-chinese-sep', 'section', '2–5'), c('mind-buddhist-sep', 'section', '2–4')], ['ethics', 'chinese-philosophy', 'buddhist-philosophy']),
  section('philosophy-of-mind', 'memory', 'Memory, imagination, and temporal cognition', [
    'Memory is not a single storehouse. Procedural memory supports skills; semantic memory concerns general knowledge; episodic memory presents experienced events; working memory sustains current tasks; prospective memory concerns intended future action. Remembering can be accurate without replaying a recording and can involve constructive reconstruction without becoming mere invention. Philosophers debate whether episodic memory requires a causal connection with the past, whether it is a form of imagining constrained by origin, and how first-person perspective, emotion, narrative, and social prompting shape recollection. Forgetting can be failure, protection, adaptation, or a condition of abstraction depending on the task.',
    'Memory supports personal continuity, testimony, responsibility, expertise, and collective identity, so unequal credibility and archival power matter. A person with memory impairment does not thereby lose all agency or personhood. Distributed practices—photographs, notebooks, oral transmission, ritual, databases, other people—support recall while introducing dependence and opportunities for manipulation. Imagination recombines memory to simulate possibilities, understand others, plan, create, and avoid danger, but imaginative ease is not evidence that a scenario is metaphysically possible. Philosophy of mind connects mechanisms of retention and reconstruction with the normative question of what should count as remembering well.',
    'Collective memory is not a group-sized copy of an individual faculty. Monuments, archives, curricula, commemorations, testimony, and silences organize what communities can retrieve and contest. Institutions can preserve accurate records while sustaining false public narratives, or repair exclusion by changing custodianship and access. Trauma may disrupt ordinary temporal integration without producing one universal symptom pattern. Philosophers should distinguish episodic recall, historical knowledge, identity-making narrative, and political commemoration before asking whether a society literally remembers.',
  ], [c('mind-self-sep', 'section', '3–5'), c('mind-extended', 'section', 'The Extended Mind'), c('mind-james', 'chapter', 'Chapters IX–X: The Stream of Thought and Consciousness of Self')], ['epistemology', 'ethics']),
  section('philosophy-of-mind', 'self', 'Self, self-consciousness, and first-person authority', [
    'Self-consciousness can mean reflective thought about oneself, immediate first-person awareness, bodily ownership, a sense of agency, or social self-recognition. Using “I” differs from identifying a person seen in a photograph, and some first-person judgments appear immune to error through misidentification without being infallible about the state attributed. Theories locate basic self-awareness in introspection, embodied experience, rational unity, narrative, or relations with others. Hume’s failure to catch a simple self in introspection does not prove that persons are unreal; it challenges one model of an inner bearer directly observed behind experience.',
    'First-person authority is also socially situated. People can have distinctive access to pain, intention, identity, or experience while misunderstanding causes, concepts, and wider structures. Others can wrongfully override avowals, yet sincere avowal does not settle every medical, legal, or metaphysical question. Intersubjective theories argue that capacities to think about oneself depend on recognizing or communicating with others. Indian and Buddhist debates distinguish enduring self, person, witness consciousness, and psychophysical continuity in ways that do not map cleanly onto narrative-self versus bundle-self taxonomies. The field should preserve both epistemic privilege and possibilities of error, development, and social formation.',
    'Narrative theories explain how agents organize lives through temporally extended interpretations, while minimal-self theories defend a more basic pre-reflective subjectivity. Narratives can support responsibility and repair, but a demand for coherent autobiography can exclude people whose memory, communication, or cultural practices do not fit it. Minimal experience may ground a point of view without supplying a substantial ego. These approaches can be complementary if they address different layers, though each becomes controversial when presented as the one thing every self must be.',
  ], [c('mind-self-sep', 'section', '1–4'), c('mind-indian-person-sep', 'section', '1–5'), c('mind-buddhist-sep', 'section', '1; 5–6')], ['epistemology', 'buddhist-philosophy', 'indian-philosophy']),
  section('philosophy-of-mind', 'personal-identity', 'Persons and identity across time', [
    'Personal identity asks what makes a person at one time the same person later. Bodily continuity, brain continuity, psychological connectedness, memory, narrative, soul, and animal-organism accounts each capture some intuitions and face counterexamples. Thought experiments about transfer, duplication, fission, and teleportation test principles but can smuggle in the very identities they ask readers to judge. Numerical identity—being one and the same entity—must be distinguished from qualitative similarity, moral identity, and practical concern. Survival may matter even when a theory doubts that a further fact of identity exists.',
    'The metaphysical question also differs from criteria used in law, medicine, kinship, and everyday relationships. Dementia, amnesia, dissociation, transplantation, and disability should not be used as spectacle or as evidence that someone is “no longer there.” They reveal tensions among biological life, psychological connection, recognition, responsibility, and care. Classical Indian traditions distinguish person and self in varied ways; Buddhist no-self arguments reject an independent permanent essence while explaining causal continuity, karma, and conventional person-talk differently across schools. Translating that position as the simple claim that personal identity never matters imports a conclusion the arguments need not support.',
  ], [c('mind-indian-person-sep', 'section', '1–5'), c('mind-buddhist-sep', 'section', '1; 5–6'), c('mind-self-sep', 'section', '4–5')], ['metaphysics', 'ethics', 'buddhist-philosophy']),
  section('philosophy-of-mind', 'cognition', 'Cognition, concepts, computation, and learning', [
    'Cognition includes perception, categorization, reasoning, planning, learning, language, imagination, and control, but researchers disagree about its boundaries. Classical computationalism models cognition as operations over representations; connectionist systems emphasize learned distributed patterns; Bayesian and predictive approaches model inference under uncertainty; dynamical systems describe temporally coupled processes; ecological and enactive accounts foreground skilled engagement. These are research frameworks, not single theories that rise and fall together. A useful model can explain one capacity without supplying a complete metaphysics of mind, and computational description can apply at several levels without implying that a brain is literally an ordinary digital computer.',
    'Concepts may be definitions, prototypes, exemplars, abilities, inferential roles, or elements in structured representations. Variation across languages and cultures challenges claims that one experimental task reveals universal conceptual structure, but it does not make comparison impossible. Development and education show cognition as plastic, social, and scaffolded. Bias can describe efficient heuristics, systematic error, or socially patterned judgment; the normative standard must be stated. Cognitive science explains how agents succeed and fail, while philosophy asks which capacities count as reasoning, whether norms can be naturalized, and how scientific categories relate to people’s own interpretations of their thought.',
    'Language and thought remain entangled without being identical. Linguistic structure can scaffold memory, abstraction, and social coordination; preverbal infants and nonlinguistic animals still display sophisticated cognition. Inner speech may guide control but is not the vehicle of every thought. Debates over modularity ask whether specialized systems are informationally encapsulated or developmentally assembled. Learning can change representations, policies, skills, or attention. General intelligence is therefore not a single observable substance: any measure selects tasks, environments, and values, making transfer and ecological validity central.',
  ], [c('mind-embodied-sep', 'section', '1–5'), c('mind-functionalism-sep', 'section', '1–5'), c('mind-behaviorism-sep', 'section', '1–5')], ['epistemology', 'philosophy-of-science']),
  section('philosophy-of-mind', 'causation', 'Mental causation and explanatory levels', [
    'Mental causation is the apparent capacity of perceptions, beliefs, desires, pain, and intentions to affect action and the world. Substance dualists face an interaction problem: how do distinct minds and bodies enter causal relations? Physicalists face a property problem: if physical causes are sufficient, what causal work remains for mental properties? Type-identity theories identify mental types with neural types; token identity permits individual events to be physical while mental kinds cross neural realizations; nonreductive views defend higher-level causal or explanatory autonomy. Epiphenomenalism preserves experience while denying some mental-to-physical causation, at a high cost to ordinary agency and evolutionary explanation.',
    'Causal exclusion arguments ask whether a physical event would be overdetermined if both a mental property and its physical realizer caused it. Responses appeal to realization, intervention, proportionality, constitution, or the legitimacy of multiple explanatory levels. A software fault and an electrical transition can both explain a crash without being rival pushes, but whether this analogy fits mind is contested. Reasons also explain action normatively—by making it intelligible—not merely as forces. A theory must clarify whether it concerns events, properties, explanations, or agents. Neuroscience can identify causal pathways while leaving open how personal-level reasons and first-person knowledge belong in a complete account.',
  ], [c('mind-causation-sep', 'section', '1–8'), c('mind-physicalism-sep', 'section', '1–7'), c('mind-dualism-sep', 'section', '3–5')], ['metaphysics', 'philosophy-of-science']),
  section('philosophy-of-mind', 'other-minds', 'Other minds, empathy, and social cognition', [
    'The traditional problem of other minds asks how observable bodies and behavior justify belief in experiences not directly accessible to us. Arguments from analogy, inference to the best explanation, criterion-based accounts, simulation theories, and theory-theory provide different answers. Everyday understanding is often direct and interactive: posture, expression, speech, and joint activity present anger, attention, or confusion without a conscious inference from neutral movements. Yet behavior can be masked, culturally variable, or ambiguous. The philosophical challenge is not to choose between perfect transparency and permanent skepticism, but to explain warranted interpersonal understanding, error, and correction.',
    'Social cognition is shaped by power. Stereotypes alter which emotions or intentions observers perceive; testimony can be discounted; norms of eye contact, speech, independence, or affect can misclassify autistic, disabled, racialized, or culturally different agents. Empathy can mean affective resonance, perspective-taking, concern, or imaginative identification, and none guarantees accurate or ethical response. Recognition sometimes requires accepting another’s authority and sometimes challenging harmful self-interpretation. Philosophies of intersubjectivity argue that selfhood itself develops through others, making the problem reciprocal: understanding another is not observation of an alien interior but participation in shared practices with persistent possibilities of opacity.',
    'Joint attention and shared intentionality show how minds coordinate around a common world. Infants follow gaze, partners establish common ground, and collaborators divide cognitive labor. These achievements do not require identical representations at every moment, but they depend on repair when coordination fails. Testimony, trust, and conversational uptake are cognitive as well as social. A solitary model of mind that treats communication as exporting completed inner contents may miss how questions, disagreement, and teaching create capacities. A purely social model, however, must still explain privacy, resistance, and thoughts that depart from group norms.',
  ], [c('mind-self-sep', 'section', '4.4 Self-consciousness and intersubjectivity'), c('mind-consciousness-sep', 'section', '2. Concepts of consciousness'), c('mind-chinese-sep', 'section', '3–5')], ['epistemology', 'feminist-philosophy', 'political-philosophy']),
  section('philosophy-of-mind', 'animal-minds', 'Animal minds and comparative cognition', [
    'Questions about animal minds concern consciousness, pain, perception, concepts, memory, planning, communication, self-awareness, culture, and agency across enormously different forms of life. Behavior must be interpreted without assuming that human language is the measure of every capacity or that any flexible performance proves a humanlike mind. Associative learning and richer cognition are not always exclusive explanations. Experimental design, species-typical ecology, sensory worlds, motivation, captivity, and replication matter. Mirror recognition, for example, tests responses to reflected bodies under particular conditions; failure does not demonstrate absence of self-awareness in every sense.',
    'Comparative research can revise concepts rather than merely grade species on a ladder. Echolocation, distributed octopus control, insect navigation, corvid caching, primate social learning, and cetacean communication pose different explanatory problems. Consciousness attribution uses converging behavioral, anatomical, evolutionary, and physiological evidence, yet uncertainty remains and has ethical consequences. Precaution may be justified before metaphysical certainty about sentience. Historical texts contain both insights and prejudices about animals; Descartes should not be reduced to a one-line denial of all animal sensation, nor should continuity claims erase morally and scientifically significant differences among species.',
    'Anthropomorphism and anthropodenial are paired errors. Projecting human motives can invent capacities, while refusing a capacity because it resembles ours can ignore evolutionary continuity and converging evidence. Morgan’s Canon advises against needlessly complex explanations but does not demand choosing the cognitively poorest story regardless of data. Field observation can reveal behavior that captive tasks miss; controlled experiments can test interpretations field observation cannot isolate. Species-appropriate welfare is both an ethical requirement and a condition for valid cognition research.',
  ], [c('mind-animal-sep', 'section', '1–8'), c('mind-consciousness-sep', 'section', '7. Other minds and consciousness'), c('mind-descartes', 'standard-division', 'Meditation VI')], ['ethics', 'philosophy-of-science']),
  section('philosophy-of-mind', 'artificial-systems', 'Artificial systems, intelligence, and consciousness', [
    'Artificial intelligence separates several questions often compressed in publicity. Can a system perform a task, learn a pattern, use language, reason, plan, or act robustly across settings? Does it understand what its symbols or outputs are about? Is it conscious, autonomous, responsible, or a moral patient? Behavioral success can be evidence for some capacities without settling all of them. Functionalists may allow multiple physical realizations of mind; biological naturalists, enactivists, embodied theorists, and others propose additional requirements. The Chinese Room and Turing-style tests target different claims. Neither a fluent dialogue nor a biological substrate functions as an uncontested criterion of consciousness.',
    'Claims about current systems should avoid transient marketing categories and unavailable internal evidence. Large-scale models can produce useful, surprising behavior through learned statistical structure while their understanding, agency, and experience remain disputed. Anthropomorphic language can mislead users, but blanket insistence that artifacts can never have minds begs the philosophical question. Evaluation should specify architecture, training, embodiment, memory, environmental coupling, goal formation, self-modeling, and evidence of valenced states. Ethical concerns about human labor, surveillance, bias, energy, misinformation, and displaced accountability are real regardless of machine consciousness and should not be postponed behind speculation about future persons.',
    'Responsibility for artificial systems remains primarily distributed among designers, deployers, institutions, users, and regulators even when systems adapt in unanticipated ways. Calling a tool an “agent” can be technically useful while laundering accountability; refusing all agency language can obscure autonomous control and interaction risk. Moral-patient questions require evidence about experience or interests, while legal-personhood questions can be settled instrumentally for governance. These classifications should not be collapsed. A corporation can have legal personhood without consciousness, and a being might warrant moral concern without being competent to bear duties.',
  ], [c('mind-ai-sep', 'section', '1–8'), c('mind-functionalism-sep', 'section', '1–5'), c('mind-embodied-sep', 'section', '1–5')], ['philosophy-of-science', 'ethics', 'philosophy-of-language']),
  section('philosophy-of-mind', 'taxonomies', 'Dualism, physicalism, behaviorism, identity, and functionalism', [
    'Substance dualism distinguishes mind and body as different substances; property dualism defends irreducible mental properties; hylomorphic approaches analyze living form and matter; physicalism holds, in varying formulations, that everything is physical or depends appropriately on the physical. Behaviorism can be a research method, a psychological theory, or an analysis of mental language. Identity theories identify mental states with brain states; functionalism individuates them by causal roles; representationalism explains mentality or experience through content. These views answer different questions and have variants that overlap. A taxonomy teaches orientation only if it also presents arguments, counterexamples, and changes in formulation.',
    'Physicalism draws support from causal closure, neural dependence, and scientific integration, but faces questions about defining the physical, consciousness, content, and explanatory sufficiency. Dualism protects some intuitions about subjectivity or identity but faces interaction, pairing, unity, and explanatory problems. Behaviorism resists unverifiable inner posits but can omit experience and internal structure. Identity theory gains ontological economy but confronts multiple realization and type individuation. Functionalism accommodates realization diversity yet faces absent-qualia, inverted-spectrum, and semantic objections. Representational theories unify perception and content but disagree about which content determines phenomenal character. No checklist decides among them without the arguments that motivate each cost.',
  ], [c('mind-dualism-sep', 'section', '1–5'), c('mind-physicalism-sep', 'section', '1–7'), c('mind-behaviorism-sep', 'section', '1–5'), c('mind-functionalism-sep', 'section', '1–5')], ['metaphysics']),
  section('philosophy-of-mind', 'alternatives', 'Phenomenology, enactivism, eliminativism, and plural explanation', [
    'Phenomenology begins from structures of lived experience—intentionality, temporality, embodiment, worldhood, and intersubjectivity—without reducing itself to introspective data collection. Enactivism treats cognition as active sense-making or skilled organism-environment engagement, though its strands disagree about representation and biological autonomy. Embodied and extended approaches move explanatory boundaries beyond isolated brain processes. These programs can be naturalistic, but “naturalism” itself ranges from continuity with science to a broader account of living nature. They do not automatically refute computational or representational explanation; hybrid theories remain possible.',
    'Eliminative materialism predicts that mature science may replace some ordinary mental categories rather than smoothly reduce them. Elimination can target propositional attitudes, qualia, or a particular folk taxonomy; it need not deny every capacity or experience. Critics argue that folk psychology is more flexible and successful than eliminativists claim, that scientific models presuppose intentional concepts, or that first-person phenomena cannot be discarded by theoretical revision. Pluralists distinguish levels and explanatory interests: neural, computational, bodily, personal, social, and phenomenological accounts may cooperate. But pluralism requires compatibility and division of labor, not the automatic protection of every vocabulary from criticism.',
  ], [c('mind-embodied-sep', 'section', '1–5'), c('mind-eliminative-sep', 'section', '1–4'), c('mind-consciousness-sep', 'section', '4–7')], ['phenomenology', 'philosophy-of-science']),
  section('philosophy-of-mind', 'ethics-politics', 'Mental difference, institutions, and moral status', [
    'Concepts of rationality, competence, normality, disorder, and personhood allocate rights and authority. Psychiatry and neurotechnology raise questions about diagnosis, coercion, treatment, consent, identity, and responsibility. A condition can involve real suffering and also be intensified by exclusionary environments; social and medical models need not be simple enemies. Neurodiversity challenges assumptions that one cognitive style defines flourishing while leaving room to address distress and support needs. Testimony about pain or disability can be discounted when outward behavior fails a dominant script. Philosophy of mind is political when its categories govern whose mind counts.',
    'Moral status may depend on consciousness, sentience, agency, relationships, species membership, potential, or combinations. Different criteria affect infants, cognitively disabled humans, animals, and possible artificial systems, creating risks of ranking existing people by idealized rational capacity. Relational and care-based theories emphasize dependency and recognition; sentience theories emphasize valenced experience; agency theories emphasize self-direction. No one criterion is unproblematic. Ethical application should separate metaphysical description from political endorsement: discovering neural difference does not determine whether it is defect, identity, or neutral variation, and establishing dependence does not authorize paternalism.',
  ], [c('mind-self-sep', 'section', '4–5'), c('mind-animal-sep', 'section', '1–8'), c('mind-ai-sep', 'section', '6–8')], ['ethics', 'political-philosophy', 'feminist-philosophy']),
  section('philosophy-of-mind', 'open-problems', 'Why the central problems remain open', [
    'Consciousness remains open because correlations and mechanisms do not yet yield agreement about subjective character, and because rival theories disagree over the explanandum. Intentionality remains open because causal and informational relations must acquire correctness conditions and aboutness without circularity. Mental causation remains open because physical sufficiency, realization, and higher-level explanation are interpreted differently. Personal identity remains open because biological, psychological, social, and practical continuities pull apart. Other minds remain open not from lack of ordinary knowledge but because first-person access, behavioral evidence, and conceptual criteria do not combine into one simple proof.',
    'Openness does not mean stalemate. Experimental methods improve, distinctions sharpen, and theories lose plausibility under counterevidence. It means no framework has earned the right to redescribe every remaining problem as solved. Dualists must engage causal and scientific evidence; physicalists must explain rather than rename experience and content; phenomenologists must connect description with interpersonal and empirical checks; enactivists must specify constitution and representation; AI claims must distinguish performance from mentality. Progress often comes from changing the question or linking levels, but conceptual revision should be argued rather than announced as victory.',
  ], [c('mind-consciousness-sep', 'section', '4–7'), c('mind-intentionality-sep', 'section', '9–10'), c('mind-causation-sep', 'section', '3–8'), c('mind-self-sep', 'section', '2–5')], ['metaphysics', 'epistemology', 'philosophy-of-science']),
  section('philosophy-of-mind', 'reading', 'A comprehensive route through mind', [
    'Begin with Descartes’s second and sixth Meditations, but pair them with objections and non-Cartesian alternatives. Read William James on the stream of thought, habit, self, and emotion; then study a guided Indian Buddhist account of aggregates and no-self and a specialist account of Chinese heart-mind. Keep a translation ledger: mind, consciousness, self, soul, person, xin, citta, vijñāna, and ātman are not interchangeable. Add a phenomenological text on intentionality and embodiment. At each stage ask what the author is explaining—substance, experience, cultivation, liberation, cognition, or personhood—and which methods make the claim answerable.',
    'For contemporary work, organize study by problems before positions. On consciousness, read Nagel with physicalist and representational replies. On cognition, compare functionalism, computation, embodied cognition, and Clark and Chalmers. On action, read Anscombe with causal and noncausal theories. Add focused work on emotion, memory, self-consciousness, mental causation, animal cognition, disability, and social cognition before turning to artificial systems. Finish by analyzing one case at several levels: first-person experience, bodily skill, neural mechanism, computational function, interpersonal interpretation, and institutional setting. A comprehensive philosophy of mind does not force those levels into one vocabulary; it explains where they cooperate and conflict.',
  ], [c('mind-descartes', 'standard-division', 'Meditations II and VI'), c('mind-james', 'chapter', 'Chapters IV, IX, X, XXV'), c('mind-buddhist-sep', 'section', '1–6'), c('mind-chinese-sep', 'section', '1–5'), c('mind-nagel', 'section', 'What Is It Like to Be a Bat?'), c('mind-extended', 'section', 'The Extended Mind')], ['metaphysics', 'epistemology', 'phenomenology', 'philosophy-of-science'], ['descartes', 'william-james', 'anscombe', 'thomas-nagel']),
];

const scienceArticle: ArticleSection[] = [
  section('philosophy-of-science', 'orientation', 'Inquiry without one universal method', [
    'Philosophy of science asks how observation, experimentation, models, explanation, measurement, confirmation, criticism, and organized communities produce knowledge. It also asks what scientific theories say exists, how sciences relate, where values enter, and how expertise deserves trust. “Science” covers practices as different as particle physics, evolutionary biology, field ecology, medicine, climate modeling, archaeology, and social research. Their objects, instruments, timescales, interventions, and ethical constraints differ. A field article should therefore explain recurrent problems without turning a textbook sequence—hypothesis, experiment, conclusion—into a universal method supposedly shared by every successful inquiry.',
    'The field is normative and historical. It evaluates evidence and explanation while studying how methods developed through institutions, instruments, classifications, funding, labor, and political conflict. History can expose contingency without proving that results are arbitrary; sociology can identify interests without deciding that evidence has no force. Philosophical analysis can distinguish discovery from justification, but actual inquiry often entangles them. Indigenous, local, artisanal, and non-European knowledge traditions raise questions about translation, authority, extraction, and plural standards. They should not be declared “science” or “nonscience” by a single inherited criterion before their practices and aims are understood.',
  ], [c('sci-method-sep', 'section', '1–4'), c('sci-social-sep', 'section', '1–7'), c('sci-feminist-sep', 'section', '1–4')], ['epistemology', 'philosophy-of-science']),
  section('philosophy-of-science', 'historical', 'From natural philosophy to organized sciences', [
    'Ancient Greek, Hellenistic, Indian, Chinese, and Islamic-world inquiries developed astronomy, medicine, mathematics, logic, optics, natural history, and causal analysis under different institutional and cosmological conditions. Medieval translation and commentary moved problems across Greek, Syriac, Arabic, Hebrew, Sanskrit, Persian, Latin, and other languages. Early modern European experimental and mathematical programs emerged through navigation, craft, commerce, empire, courts, academies, printing, and inherited scholarship. Bacon’s idols, natural histories, tables, experiments, and cooperative reform form a complex program; he did not invent empirical inquiry or a mechanical recipe now followed by every science.',
    'Nineteenth-century disciplines professionalized through laboratories, surveys, museums, statistics, universities, states, and colonial collection. Twentieth-century philosophy emphasized logic, probability, theory testing, explanation, paradigms, and realism, while history and social studies challenged heroic narratives. The same institutions that enabled coordination also excluded people, appropriated specimens and knowledge, and linked classification with governance. This history does not discredit every result by association. It changes the questions: which materials and labor made evidence possible, whose categories organized data, how criticism was distributed, and whether present standards can correct the injustices embedded in scientific formation.',
  ], [c('sci-method-sep', 'section', '2. Historical review'), c('sci-bacon', 'standard-division', 'Book I, aphorisms 19–130; Book II'), c('sci-social-sep', 'section', '1. Historical background')], ['empiricism', 'islamic-philosophy'], ['bacon', 'galileo']),
  section('philosophy-of-science', 'induction-confirmation', 'Induction, confirmation, and severe testing', [
    'Inductive reasoning moves beyond observed cases: from samples to populations, past regularities to future events, or data to hypotheses. Hume argues that experience does not deductively establish the uniformity presupposed in such projection; custom explains expectation without providing demonstrative proof. Modern confirmation theories ask when evidence raises support. Hypothetico-deductive accounts test consequences, Bayesian accounts update probabilities, and error-statistical approaches emphasize severe probes. Each requires choices about background knowledge, likelihoods, alternatives, and experimental design. Evidence can favor a hypothesis without proving it true and can disconfirm one formulation without identifying the correct replacement.',
    'Popper’s falsifiability demands exposure to possible refutation, but tests do not confront isolated theories. Auxiliary assumptions, instrument reliability, data processing, and accepted basic statements help produce predictions. One anomalous result therefore does not mechanically kill a theory, while endless ad hoc rescue can empty testing of force. Corroboration is not probability or verification. Replication, robustness across methods, preregistration, exploratory analysis, and model checking address different errors and do not guarantee truth automatically. Confirmation is strongest when researchers specify alternatives, search for ways they could be wrong, and preserve enough transparency for independent criticism.',
  ], [c('sci-hume', 'standard-division', 'Sections IV–VII'), c('sci-confirmation-sep', 'section', '1–5'), c('sci-popper', 'chapter', 'Parts I–II')], ['epistemology', 'skepticism'], ['hume', 'popper']),
  section('philosophy-of-science', 'explanation', 'Explanation, causation, laws, and mechanisms', [
    'Scientific explanation can derive phenomena from laws and conditions, identify causes or mechanisms, unify patterns, show dependence under interventions, or answer a context-sensitive why-question. Hempel’s deductive-nomological model clarified the role of lawlike generalization but faces cases where derivation lacks explanatory relevance or gets direction wrong. Statistical, causal-mechanical, unificationist, interventionist, and pragmatic accounts repair different problems. No single model fits every explanation: evolutionary, historical, mathematical, mechanistic, and equilibrium explanations may succeed through different structures. Prediction and explanation can come apart, since accurate forecasting need not reveal why and good explanation need not enable precise prediction.',
    'Laws may be regularities, governing relations, features of best systems, or expressions of dispositions; special sciences often use ceteris paribus generalizations and models rather than exceptionless universal laws. Mechanistic explanation identifies organized entities and activities that produce a phenomenon, especially in biology and neuroscience, but a mechanism is more than a list of parts. Causal models represent dependence under interventions while idealizing background conditions. Some explanations are noncausal, as when mathematics constrains possible outcomes. The question is not whether every science secretly uses physics-style laws, but what makes an account relevant, stable, informative, and answerable to evidence in its domain.',
  ], [c('sci-explanation-sep', 'section', '1–7'), c('sci-method-sep', 'section', '3–4')], ['metaphysics', 'philosophy-of-mind']),
  section('philosophy-of-science', 'models', 'Models, idealization, simulation, and representation', [
    'Models include equations, diagrams, organisms, physical replicas, computer simulations, statistical structures, and conceptual systems. They may represent a target, instantiate a theory, explore possibilities, organize data, or mediate between theory and experiment. Idealizations deliberately distort: frictionless planes, infinite populations, representative agents, and simplified climate grids can isolate dependencies or make calculation possible. A false assumption does not automatically make a model useless, but success requires an account of which features matter, how results travel to the target, and where the distortion breaks down. Fit to existing data alone can conceal overfitting or wrong causal structure.',
    'Computer simulation combines theory, numerical methods, code, parameter choices, hardware, data, and visualization. Verification asks whether code solves the intended formal problem; validation asks whether the model adequately represents its target for a purpose; uncertainty analysis tracks sensitivity and limits. Machine-learning models can predict without transparent mechanisms, reviving distinctions among accuracy, explanation, causal inference, and understanding. Model pluralism may be productive when different representations capture different scales or questions. Yet incompatible models cannot always be reconciled by saying each has a perspective; investigators must test whether their domains, approximations, and outputs support the intended use.',
  ], [c('sci-models-sep', 'section', '1–6'), c('sci-observation-sep', 'section', '2–4')], ['philosophy-of-science', 'epistemology']),
  section('philosophy-of-science', 'measurement', 'Measurement, observation, experiment, and instruments', [
    'Observation is not a passive imprint of nature. Telescopes, microscopes, sequencers, surveys, archives, sensors, and statistical pipelines create access through trained practices and background theory. Theory-ladenness does not imply that observers see whatever they expect: instruments can surprise, independent techniques can converge, calibration can expose error, and data can be reused for unanticipated questions. Still, raw data are not simply given. Selection, cleaning, classification, visualization, and storage shape what becomes evidence. Philosophers distinguish data from phenomena and ask how stable patterns are inferred from local, noisy outputs.',
    'Measurement coordinates a property with a representation through procedures, models, standards, and uncertainty. A reading becomes a temperature, concentration, intelligence score, or poverty rate only within a measurement system whose validity can be challenged. Traceability and calibration connect instruments across laboratories; operationalization links abstract constructs to indicators. Experimenters intervene, control, randomize, manipulate, and sometimes learn through exploratory tinkering rather than testing a prior theory. Ethical and practical limits alter design in medicine, ecology, and social science. Reliable evidence depends on material craft, maintenance, sample construction, and institutional memory as much as on formal inference.',
  ], [c('sci-observation-sep', 'section', '1–4'), c('sci-measurement-sep', 'section', '1–8')], ['epistemology']),
  section('philosophy-of-science', 'realism', 'Realism, instrumentalism, and underdetermination', [
    'Scientific realists generally hold that successful theories aim at truth and warrant belief in at least some claims about observable and unobservable reality. Antirealists may emphasize empirical adequacy, structural continuity, agnosticism about unobservables, or the historical failure of once-successful theories. Instrumentalism can treat theories primarily as tools for prediction, though the term covers several positions. The no-miracles argument appeals to success; pessimistic inductions cite discarded entities; underdetermination asks whether evidence selects one theory among rivals. These are families of arguments, not a referendum on whether science is “real.”',
    'Selective realisms commit to well-supported structures, entities, or causal capacities rather than entire theories. Entity realism emphasizes successful intervention; structural realism emphasizes preserved relations; perspectival views emphasize historically situated yet constrained representation. Classification complicates realism: species, diseases, intelligence, and social kinds can be real without possessing timeless essences. Underdetermination varies from temporary lack of data to principled equivalence and should not be invoked generically. Realist commitment is strongest where multiple independent practices detect, manipulate, and explain stable phenomena, but even there history advises fallibilism about description and ontology.',
  ], [c('sci-realism-sep', 'section', '1–5'), c('sci-models-sep', 'section', '1; 5–6'), c('sci-observation-sep', 'section', '3–4')], ['ontology', 'metaphysics']),
  section('philosophy-of-science', 'reduction-emergence', 'Reduction, emergence, and unity across sciences', [
    'Reduction can mean deriving one theory from another, identifying entities, explaining a system through components, or replacing a vocabulary. These are not equivalent. Genetics relates to molecular biology, thermodynamics to statistical mechanics, and psychology to neuroscience through models, approximations, and many-to-one relations that complicate strict derivation. Higher-level kinds can be multiply realized and explanatorily useful while depending on lower-level processes. A successful reductive explanation does not show that organisms or persons are unreal, and failure of reduction does not establish mysterious forces.',
    'Emergence can denote unexpected collective behavior, explanatory autonomy, novel causal organization, or stronger ontological novelty. Weak emergence often concerns patterns derivable only through simulation or system-level analysis; strong emergence makes more controversial claims about irreducible powers. Complex systems display feedback, path dependence, scale interaction, and tipping behavior, challenging simple linear models. Unity of science may mean shared methods, connected theories, a common ontology, or cooperation across disciplines. Pluralism can respect domain-specific explanations without abandoning cross-checking. The task is to map relations among levels, not to assume that lower always means more real.',
  ], [c('sci-explanation-sep', 'section', '4–7'), c('sci-models-sep', 'section', '5.2 Models and reductionism'), c('sci-realism-sep', 'section', '1–5')], ['ontology', 'philosophy-of-mind']),
  section('philosophy-of-science', 'change', 'Scientific change, paradigms, and historical contingency', [
    'Kuhn describes normal science as puzzle solving organized by shared exemplars, standards, instruments, and commitments. Anomalies are expected and do not automatically cause crisis. Revolutionary change can reorganize problems, taxonomies, and standards, making translation and comparison difficult. “Paradigm” was broad in the first edition of Structure; Kuhn later distinguished disciplinary matrices and exemplars. Incommensurability does not mean total incomparability, private worlds, or evidence-free conversion. Scientists can argue across change using accuracy, scope, consistency, simplicity, fruitfulness, and other values, though those values do not operate as a decision algorithm.',
    'Scientific change can be cumulative in data or technique while discontinuous in concepts. Research programs can coexist, specialties split, and instruments stabilize results across theoretical shifts. Political events, patronage, war, public health, funding, and disciplinary institutions affect which problems are pursued without fully determining answers. Historical contingency challenges inevitability stories: another path might have produced different classifications or models. It does not follow that every path would work equally well. Counterfactual histories and attention to excluded alternatives can improve current inquiry by revealing assumptions and “unconceived alternatives.”',
  ], [c('sci-kuhn', 'standard-division', 'Sections II–XIII and Postscript—1969'), c('sci-change-sep', 'section', '3–6'), c('sci-social-sep', 'section', '1–5')], ['philosophy-of-science'], ['kuhn']),
  section('philosophy-of-science', 'values-objectivity', 'Values, objectivity, feminist and decolonial critique', [
    'Values enter science when communities choose questions, set evidential thresholds, classify populations, design technologies, communicate uncertainty, and decide which errors are most dangerous. This does not imply that evidence is whatever politics prefers. The distinction between epistemic and social values is useful but porous: simplicity, explanatory power, public benefit, consent, and risk can interact. The value-free ideal protects inquiry from wishful thinking and coercion, yet it can hide value judgments already built into methods. Responsible science makes choices explicit, subjects them to criticism, and prevents desired outcomes from substituting for evidence.',
    'Feminist philosophers of science show how exclusion can narrow questions, naturalize hierarchy, or produce ignorance, while diverse and accountable critical communities can strengthen objectivity. Standpoint approaches do not make identity infallible; contextual empiricism does not make standards optional. Decolonial critique examines extraction of land, bodies, specimens, data, and knowledge, as well as classifications tied to empire. Indigenous knowledge is internally diverse and should not be romanticized as holistic consensus or mined for decontextualized facts. Collaboration requires authority, reciprocity, provenance, and sometimes refusal. These critiques are philosophy of science because they concern evidence, categories, institutions, and epistemic success.',
  ], [c('sci-feminist-sep', 'section', '2–5'), c('sci-social-sep', 'section', '3–6'), c('sci-observation-sep', 'section', '3.4 Values')], ['feminist-philosophy', 'political-philosophy']),
  section('philosophy-of-science', 'organization-trust', 'Institutions, expertise, funding, and public trust', [
    'Modern science depends on divided cognitive labor. No individual can reproduce every result, so researchers and publics rely on testimony, peer review, journals, laboratories, regulators, professional communities, and infrastructures. Peer review can filter errors and also reproduce prestige, secrecy, and bias. Replication is valuable but not always possible or the only standard; triangulation, data audits, prospective prediction, and mechanistic understanding may matter more in some fields. Funding directs attention, creates conflicts, and sustains expensive long-term work. Industry, government, philanthropy, and public funding pose different accountability problems rather than a clean public/private divide.',
    'Trustworthy expertise is neither blind deference nor do-it-yourself replication. Nonexperts can assess track records, relevant consensus, transparency, conflicts, responsiveness to criticism, and institutional safeguards. Disagreement among experts may reflect uncertainty, values, specialties, or genuine evidential division. Public distrust can be irrational, but communities harmed by medicine, environmental policy, or extractive research can have warranted reasons for caution. Rebuilding trust requires trustworthy conduct: honest uncertainty, correction, participation, access, and consequences for misconduct. Public communication should distinguish uncertainty from ignorance and avoid using “the science” to conceal political decisions about acceptable risk.',
  ], [c('sci-social-sep', 'section', '2–7'), c('sci-feminist-sep', 'section', '3–5')], ['epistemology', 'political-philosophy']),
  section('philosophy-of-science', 'reading', 'Reading science through arguments and practices', [
    'Begin with Hume on induction and Bacon on idols and organized inquiry, while resisting a story in which one doubts and the other discovers “the method.” Study a historical experiment in detail: instrument construction, sample, calibration, representation, publication, labor, and dispute. Then compare Popper’s testing with Bayesian confirmation and error-statistical approaches. Read Kuhn’s chapters on normal science before the famous revolution chapters and include his 1969 postscript. Ask which claims are descriptive history, which are methodological norms, and which concern the ontology or semantics of theories.',
    'Continue by following one scientific case across explanation, causation, modeling, measurement, realism, values, and institutions. Pair canonical debates with feminist and decolonial philosophy of science and with scholarship on the case’s material and political history. Examine a failed or revised classification as well as a success. For a contemporary controversy, separate empirical findings, model assumptions, uncertainty, ethical tradeoffs, institutional authority, and policy choice. The mature question is not whether science follows a universal recipe or is socially constructed. It is how specific practices make claims reliable, revisable, meaningful, and publicly answerable under real historical conditions.',
  ], [c('sci-hume', 'standard-division', 'Sections IV–VII'), c('sci-bacon', 'standard-division', 'Books I–II'), c('sci-popper', 'chapter', 'Parts I–II'), c('sci-kuhn', 'standard-division', 'Sections II–XIII and Postscript—1969'), c('sci-social-sep', 'section', '1–7')], ['epistemology', 'feminist-philosophy'], ['hume', 'bacon', 'popper', 'kuhn']),
];

type EvidenceGroups = {
  classification: CitationReference[];
  chronology: CitationReference[];
  concepts: CitationReference[];
  works: CitationReference[];
  relationships: CitationReference[];
  disputes: CitationReference[];
  reading: CitationReference[];
};

type CoreFieldConfig = {
  sources: EditorialSource[];
  articleSections: ArticleSection[];
  patch: Partial<Branch>;
  evidence: EvidenceGroups;
  reviewNotePath: string;
};

const serialize = (value: unknown): string => JSON.stringify(value) ?? 'null';

const structuredClaims = (record: Branch, evidence: EvidenceGroups) => ({
  classification: claim(record.category, evidence.classification),
  'date-anchor': claim(`${record.roughStartYear}: ${record.originPeriod}`, evidence.chronology),
  'origin-story': claim(record.originStory ?? '', evidence.chronology),
  'short-definition': claim(record.shortDefinition, evidence.classification),
  purpose: claim(record.oneSentencePurpose, evidence.classification),
  'beginner-explanation': claim(record.beginnerExplanation, evidence.concepts),
  'core-questions': claim(serialize(record.coreQuestions), evidence.concepts),
  'historical-development': claim(serialize(record.historicalDevelopmentDetailed ?? record.historicalDevelopment), evidence.chronology),
  terminology: claim(serialize(record.keyConcepts), evidence.concepts),
  'detailed-concepts': claim(serialize(record.keyConceptsDetailed), evidence.concepts),
  classifications: claim(serialize(record.subBranches), evidence.classification),
  relationships: claim(serialize({related: record.relatedBranchIds, contrasting: record.contrastingBranchIds, rivals: record.rivalPositions}), evidence.relationships),
  'major-figures': claim(serialize(record.majorFigures ?? record.majorPhilosopherIds), evidence.relationships),
  chronology: claim(serialize(record.timelineEventIds), evidence.chronology),
  works: claim(serialize(record.majorWorks), evidence.works),
  debates: claim(serialize({internal: record.internalDebates, tensions: record.internalTensions}), evidence.disputes),
  misunderstandings: claim(serialize(record.misconceptionsDetailed ?? record.commonMisunderstandings), evidence.disputes),
  applications: claim(serialize(record.modernRelevanceDetailed ?? record.modernExamples), evidence.concepts),
  'reading-path': claim(serialize({beginner: record.beginnerReadingPath, advanced: record.advancedReadingPath}), evidence.reading),
});

